insert into tax_templates
  (country, code, name, name_i18n, description, amount_type, amount, applies_to, treatment,
   valid_from, valid_to, legal_reference, vat_category, exemption_code, sequence,
   tax_kind, recoverable, conditions, jurisdiction, price_include, cash_basis,
   cash_basis_transition_account_code, source_key,
   applies_seller_territory, applies_buyer_territory, applies_supply_territory,
   applies_supply_vs_seller)
values
  ('KG', 'KG-P-12', 'НДС 12 % — основная ставка (покупка)', '{"en":"VAT 12% — standard rate (purchase)"}'::jsonb, null, 'percent', 12, 'purchase', 'domestic', date '2022-01-01', null, 'Налоговый кодекс, статья 254, часть 1 и статья 315, часть 1 — налогоплательщик НДС вправе зачесть НДС, уплаченный или подлежащий уплате за приобретенные материальные ресурсы, используемые для создания облагаемых поставок.', null, null, 70, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'tax-code', null, null, null, null),
  ('KG', 'KG-P-12-NR', 'НДС 12 % — услуги нерезидента (налоговый агент)', '{"en":"VAT 12% — services from a non-resident (tax agent)"}'::jsonb, 'НДС, который налоговый агент — получатель услуг нерезидента исчисляет и уплачивает в бюджет и который принимается к зачету только после уплаты', 'percent', 12, 'purchase', 'foreign_services_received', date '2022-01-01', null, 'Налоговый кодекс, статья 263, часть 1, пункт 4 — консультационные, юридические, бухгалтерские, аудиторские, рекламные и иные перечисленные услуги, приобретаемые налогоплательщиком Кыргызской Республики, оказаны на ее территории; статья 254(1) — ставка 12 %; статья 315, часть 3, пункт 4 — налогоплательщик НДС, приобретающий у иностранной организации без постоянного учреждения услуги с местом поставки в Кыргызской Республике, зачитывает НДС при условии, что НДС уплачен в бюджет и оформлен счет-фактура в свой адрес. Начисленный налог ждет на 3433, зачет — на 1543, без ячейки отчета за период покупки: перенос на 1541 и в ячейку INPUT в период уплаты — ручная запись, см. README.md.', null, null, 60, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'tax-code', null, null, null, null),
  ('KG', 'KG-S-12', 'НДС 12 % — основная ставка (продажа)', '{"en":"VAT 12% — standard rate (sale)"}'::jsonb, null, 'percent', 12, 'sale', 'domestic', date '2022-01-01', null, 'Налоговый кодекс, статья 254, часть 1 — ставка НДС устанавливается в размере 12 процентов от облагаемой поставки и облагаемого импорта, если иное не предусмотрено Кодексом.', null, null, 10, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'tax-code', null, null, null, null),
  ('KG', 'KG-S-EXEMPT-BOOKS', 'Освобождено от НДС — учебники, научные и литературно-художественные книги, детские издания и журналы на государственном языке (продажа)', '{"en":"VAT-exempt — textbooks, scientific and literary books, children’s publications and journals in the state language (sale)"}'::jsonb, null, 'percent', 0, 'sale', 'exempt', date '2022-01-01', null, 'Налоговый кодекс, статья 276 — поставка учебников, хрестоматий, научных, литературно-художественных книг, изданий для детей, журналов на государственном языке является поставкой, освобожденной от НДС (статья 264 отсылает к статьям 265–296).', null, null, 40, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'tax-code', null, null, null, null),
  ('KG', 'KG-S-EXEMPT-REALESTATE', 'Освобождено от НДС — жилые помещения и земельные участки (продажа или аренда)', '{"en":"VAT-exempt — residential premises and land (sale or lease)"}'::jsonb, null, 'percent', 0, 'sale', 'exempt', date '2022-01-01', null, 'Налоговый кодекс, статья 265, часть 1, пункты 1 и 2 — реализация жилых зданий и помещений жилищного фонда или их аренда (кроме помещений гостиничного типа, пансионатов, здравниц) и земельных участков является поставкой, освобожденной от НДС.', null, null, 50, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'tax-code', null, null, null, null),
  ('KG', 'KG-S-ZERO-EXPORT', 'НДС 0 % — экспорт товаров (продажа)', '{"en":"VAT 0% — export of goods (sale)"}'::jsonb, null, 'percent', 0, 'sale', 'export', date '2022-01-01', null, 'Налоговый кодекс, статья 254, часть 2 и статья 303 — экспорт товаров, за исключением металлосодержащих руд, концентратов, сплавов и аффинированных металлов, является поставкой с нулевой ставкой; при экспорте в государство — член ЕАЭС документы представляются в течение 180 дней с даты отгрузки вместе с отчетностью по НДС.', null, null, 20, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'tax-code', null, null, null, null),
  ('KG', 'KG-S-ZERO-TRANSPORT', 'НДС 0 % — международные перевозки (продажа)', '{"en":"VAT 0% — international transport (sale)"}'::jsonb, null, 'percent', 0, 'sale', 'export', date '2022-01-01', null, 'Налоговый кодекс, статья 254, часть 2 и статья 304 — международная перевозка пассажиров, багажа и грузов, за исключением перевозок железнодорожным транспортом, является поставкой с нулевой ставкой.', null, null, 30, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'tax-code', null, null, null, null)
on conflict (country, code) do update set
  name            = excluded.name,
  name_i18n       = excluded.name_i18n,
  description     = excluded.description,
  amount_type     = excluded.amount_type,
  amount          = excluded.amount,
  applies_to      = excluded.applies_to,
  treatment       = excluded.treatment,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference,
  vat_category    = excluded.vat_category,
  exemption_code  = excluded.exemption_code,
  sequence        = excluded.sequence,
  tax_kind        = excluded.tax_kind,
  recoverable     = excluded.recoverable,
  conditions      = excluded.conditions,
  jurisdiction    = excluded.jurisdiction,
  price_include   = excluded.price_include,
  cash_basis      = excluded.cash_basis,
  cash_basis_transition_account_code = excluded.cash_basis_transition_account_code,
  source_key      = excluded.source_key,
  applies_seller_territory = excluded.applies_seller_territory,
  applies_buyer_territory  = excluded.applies_buyer_territory,
  applies_supply_territory = excluded.applies_supply_territory,
  applies_supply_vs_seller = excluded.applies_supply_vs_seller;

