    ('KG-P-12', 'credit_note', 'base', 100, null, 'INPUT', array['INPUT']::text[], -100, 'KG-VAT', 10),
    ('KG-P-12', 'credit_note', 'tax', 100, '1541', 'INPUT', array['INPUT']::text[], -100, 'KG-VAT', 20),
    ('KG-P-12-NR', 'invoice', 'base', 100, null, null, null, 100, null, 10),
    ('KG-P-12-NR', 'invoice', 'tax', 100, '1543', null, null, 100, null, 20),
    ('KG-P-12-NR', 'invoice', 'tax', -100, '3433', null, null, 100, null, 30),
    ('KG-P-12-NR', 'credit_note', 'base', 100, null, null, null, 100, null, 10),
    ('KG-P-12-NR', 'credit_note', 'tax', 100, '1543', null, null, 100, null, 20),
    ('KG-P-12-NR', 'credit_note', 'tax', -100, '3433', null, null, 100, null, 30),
    ('KG-S-12', 'invoice', 'base', 100, null, 'TAXABLE', array['TAXABLE']::text[], 100, 'KG-VAT', 10),
    ('KG-S-12', 'invoice', 'tax', 100, '3431', 'TAXABLE', array['TAXABLE']::text[], 100, 'KG-VAT', 20),
    ('KG-S-12', 'credit_note', 'base', 100, null, 'TAXABLE', array['TAXABLE']::text[], -100, 'KG-VAT', 10),
    ('KG-S-12', 'credit_note', 'tax', 100, '3431', 'TAXABLE', array['TAXABLE']::text[], -100, 'KG-VAT', 20),
    ('KG-S-EXEMPT-BOOKS', 'invoice', 'base', 100, null, 'EXEMPT', array['EXEMPT']::text[], 100, 'KG-VAT', 10),
    ('KG-S-EXEMPT-BOOKS', 'credit_note', 'base', 100, null, 'EXEMPT', array['EXEMPT']::text[], -100, 'KG-VAT', 10),
    ('KG-S-EXEMPT-REALESTATE', 'invoice', 'base', 100, null, 'EXEMPT', array['EXEMPT']::text[], 100, 'KG-VAT', 10),
    ('KG-S-EXEMPT-REALESTATE', 'credit_note', 'base', 100, null, 'EXEMPT', array['EXEMPT']::text[], -100, 'KG-VAT', 10),
    ('KG-S-ZERO-EXPORT', 'invoice', 'base', 100, null, 'ZERO', array['ZERO']::text[], 100, 'KG-VAT', 10),
    ('KG-S-ZERO-EXPORT', 'credit_note', 'base', 100, null, 'ZERO', array['ZERO']::text[], -100, 'KG-VAT', 10),
