insert into tax_report_templates
  (country, code, name, periods, period_default, valid_from, valid_to, legal_reference,
   is_periodic_return, deadline_rule, deadline_day, deadline_plus_days,
   deadline_reference, deadline_source_key, file_format)
values
  ('KG', 'KG-VAT', 'Отчет по налогу на добавленную стоимость', array['month']::declaration_period[], 'month'::declaration_period, date '2022-01-01', null, 'Налоговый кодекс, статья 313 — налоговый период по НДС по облагаемым поставкам — один календарный месяц (для иностранной организации, оказывающей электронные услуги, — квартал); статья 314 — порядок исчисления; статья 319 — срок представления отчетности. Форма отчета по НДС и нумерация ее строк утверждаются актом, текст которого не удалось прочитать из открытых источников; поэтому ячейки этого отчета названы по статьям Кодекса (TAXABLE, ZERO, EXEMPT, TURNOVER, INPUT, CREDIT, PAYABLE, EXCESS), а не по номерам строк официальной формы, и не воспроизводят ее приложений. См. README.md.', true,'day_of_month_after_period'::filing_deadline_rule, 25, null, 'Налоговый кодекс, статья 319, часть 1, пункт 1 и часть 2 — отчетность по НДС представляется и НДС уплачивается не позднее 25 числа месяца, следующего за отчетным налоговым периодом. Для налогоплательщиков, обслуживаемых специализированным подразделением налоговой службы, срок представления — не позднее последнего дня месяца, следующего за периодом (пункт 2): этот срок формат одной строкой не выражает.', 'tax-code', null)
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
  period_default      = excluded.period_default,
  valid_from          = excluded.valid_from,
  valid_to            = excluded.valid_to,
  legal_reference     = excluded.legal_reference,
  is_periodic_return  = excluded.is_periodic_return,
  deadline_rule       = excluded.deadline_rule,
  deadline_day        = excluded.deadline_day,
  deadline_plus_days  = excluded.deadline_plus_days,
  deadline_reference  = excluded.deadline_reference,
  deadline_source_key = excluded.deadline_source_key,
  file_format         = excluded.file_format;

insert into tax_report_box_templates
  (country, report_code, box, kind, name, name_i18n, sequence, print_sequence,
   plus_boxes, minus_boxes, rate, rate_of_box, floor_zero, hidden, xml_element,
   legal_reference, source_key)
values
