values
  ('KG-BS', 'KG', 'default', 'Бухгалтерский баланс', 'balance_sheet', 'МСФО', date '2022-01-01', null, 'Постановление Правительства № 231 от 07.10.2010 и МСФО (IAS 1) — структура баланса. Строки этой десте собраны из разделов плана счетов (1000 — оборотные активы, 2000 — внеоборотные, 3000 — краткосрочные обязательства, 4000 — долгосрочные, 5000 — капитал); это сборка самой десте, а не утвержденная форма баланса, которую в открытых источниках прочитать не удалось. См. README.md.', 'coa-resolution-231', 'combined', 'Результат текущего финансового года', '{"en":"Result of the current financial year"}'::jsonb),
  ('KG-IS', 'KG', 'default', 'Отчет о прибылях и убытках', 'income_statement', 'МСФО', date '2022-01-01', null, 'Постановление Правительства № 231 от 07.10.2010 и МСФО (IAS 1) — структура отчета о прибылях и убытках. Строки собраны из разделов 6000 (доходы), 7000 (операционные расходы), 8000 (общие и административные), 9000 (неоперационные) плана счетов; это сборка самой десте, а не утвержденная форма. См. README.md.', 'coa-resolution-231', null, null, '{}'::jsonb)
